CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE TABLE IF NOT EXISTS anonymous_sessions(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),nickname VARCHAR(64) NOT NULL,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,last_active TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,is_banned BOOLEAN DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS chat_rooms(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),slug VARCHAR(64) UNIQUE NOT NULL,name VARCHAR(128) NOT NULL,description TEXT,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS chat_messages(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),room_id UUID REFERENCES chat_rooms(id) ON DELETE CASCADE,session_id UUID REFERENCES anonymous_sessions(id) ON DELETE SET NULL,nickname VARCHAR(64) NOT NULL,content TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS posts(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),category VARCHAR(64) NOT NULL,title VARCHAR(256) NOT NULL,content TEXT NOT NULL,nickname VARCHAR(64) NOT NULL,session_id UUID REFERENCES anonymous_sessions(id) ON DELETE SET NULL,image_url TEXT,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,reports_count INT DEFAULT 0);
CREATE TABLE IF NOT EXISTS comments(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),post_id UUID REFERENCES posts(id) ON DELETE CASCADE,session_id UUID REFERENCES anonymous_sessions(id) ON DELETE SET NULL,nickname VARCHAR(64) NOT NULL,content TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reports(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),target_type VARCHAR(32) NOT NULL,target_id UUID NOT NULL,reason TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,status VARCHAR(32) DEFAULT 'pending');
CREATE INDEX IF NOT EXISTS idx_posts_created ON posts(created_at DESC);CREATE INDEX IF NOT EXISTS idx_messages_room ON chat_messages(room_id,created_at DESC);
INSERT INTO chat_rooms(slug,name,description) VALUES('general-india','General India','Open discussions about anything related to India.'),('madhya-pradesh','Madhya Pradesh','Local chat for Madhya Pradesh discussions.'),('mumbai','Mumbai','Conversations from the city of dreams.'),('delhi','Delhi','NCR news, food, and discussions.'),('students','Students','Exams, colleges, career advice, and student life.'),('technology','Technology','Coding, startups, AI, and tech trends.'),('relationships','Relationships','Dating, marriage, and personal advice.'),('random','Random','Unfiltered thoughts and casual chats.') ON CONFLICT(slug) DO NOTHING;